"""Assemble operator deliverables only from saved observations."""
import pathlib,csv,json,collections,datetime
r=pathlib.Path(__file__).resolve().parents[1];csv.field_size_limit(536870912)
machines=('alma','void','gentoo','microos','talos')
releases={'alma':'10.3','void':'20250202 (rolling-release installation image)','gentoo':'stage3-amd64-openrc-20261122T164601Z','microos':'Snapshot20261121 plain x86_64 KVM/XEN image','talos':'1.14.6'}
read=lambda p:list(csv.DictReader(p.open(),delimiter='\t'))
summaries={}
for m in machines:
 assert (r/f'part-{m}.tsv').is_file() and (r/f'{m}-FACTS.md').is_file()
 raw=r/'raw'/m
 if not (raw/'objects.tsv').exists():
  summaries[m]={'inventory':False,'total':0,'levels':{},'counts':{},'reasons':'N/A (no inventory)','integrity':'N/A (no inventory)'};continue
 objects=read(raw/'objects.tsv');packages=[json.loads(a['members']) for a in objects if a['kind']=='package'];files=read(raw/'package-files.tsv');coverage=read(raw/'coverage.tsv')
 known=sum(isinstance(a,dict) and a.get('reason') in ('explicit','dependency') for a in packages);fknown=sum(a['integrity'] in ('unchanged','changed','missing') for a in files)
 def share(a,b):return f'{a}/{b} ({100*a/b:.2f}%)' if b else 'N/A (zero denominator)'
 summaries[m]={'inventory':True,'total':len(objects),'levels':dict(collections.Counter(a['level'] for a in objects)),'counts':dict(collections.Counter('L'+a['level']+':'+a['kind'] for a in objects)),'reasons':share(known,len(packages)),'integrity':share(fknown,len(files)),'failed_queries':sum(int(a['exit_status'])!=0 for a in coverage),'queries':len(coverage),'metadata':json.loads((raw/'metadata.json').read_text())}
now=datetime.datetime.now(datetime.timezone.utc).isoformat();lines=[f'INVENTORY: {sum(s["inventory"] for s in summaries.values())} of 5 machines','',f'Recorded UTC: {now}.','','Input commit: `b3c3c141c612b8d287c8058733141cb56d1c2431`, supplied by `GATES/INPUTS-PUSHED`. All 1020 manifest entries matched before observation; all 44 staged runtime files matched after transfer. The laboratory runner also matched. Evidence: `control/input-verification.json`, `control/input-verification.tsv`, `control/deployed-input-verification.json`, `control/OPERATOR-NOTES.md`. The manifest has no self-checksum. This workspace is not a Git worktree; commit-tree identity was not independently verified.','','## Machine records','','Counts mean rows emitted by the committed collector, without selection, merging or deduplication. The second-level column reports the requested rows-above-zero condition. It does not resolve whether bounded or partial coverage satisfies Section 9.2, and assigns no hypothesis outcome. Known reasons mean explicit/dependency; known integrity means unchanged/changed/missing. Packaged-file shares use all collector package/file records, not unique paths.','','| Machine | Committed release | Objects | L1 | L2 | Second-level rows obtained | Known package reasons | Known packaged-file integrity |','|---|---|---:|---:|---:|---|---|---|']
for m,s in summaries.items():lines.append(f'| {m} | {releases[m]} | {s["total"]} | {s["levels"].get("1",0)} | {s["levels"].get("2",0)} | {"Yes" if s["levels"].get("2",0)>0 else "No"} | {s["reasons"]} | {s["integrity"]} |')
lines+=['','Gentoo: no inventory. The sole fresh-machine command returned 1 with `lab: VM failed to start`; destruction returned 0. Actions and collection were not attempted. The host lifecycle log confirms process exit 1 but provides no specific cause; slot shortage is not inferred. Evidence: `raw/gentoo/NOT-RUN.md`, `control/gentoo/new.err`, `control/gentoo/status.json`, `control/gentoo/host-lifecycle.txt`. The part table is header-only.','','## Objects by kind','','All values below are observed row counts; zero does not establish absence outside the collector scope.','','| Kind | alma | void | gentoo | microos | talos |','|---|---:|---:|---:|---:|---:|']
for kind in sorted(set().union(*(s['counts'] for s in summaries.values()))):lines.append('| '+kind+' | '+' | '.join(str(summaries[m]['counts'].get(kind,0)) for m in machines)+' |')
lines+=['','## Ordinary actions','','AlmaLinux and Void each execute their committed entry script once. The script continues its fixed list after an action failure; no action is repaired or replaced. Gentoo could not reach the action stage. No ordinary actions are prescribed for MicroOS or Talos.','','| Machine | Action/status label | Exit status | Elapsed seconds | Exact stdout | Exact stderr |','|---|---|---:|---:|---|---|']
for m in ('alma','void'):
 p=r/'control'/m/'actions-status.tsv'
 if p.is_dir():p=p/'actions-status.tsv'
 assert p.is_file()
 logdir=r/'control'/m/'actions-logs'
 if (logdir/'actions-logs').is_dir():logdir=logdir/'actions-logs'
 for a in csv.reader(p.open(),delimiter='\t'):
  name,rc,seconds=a;stem=str((logdir/name).relative_to(r))
  # Internal Void language substeps are recorded by the unchanged action runner;
  # they share the parent action output file rather than separate log files.
  if not (r/(stem+'.log')).exists():stem=str((logdir/'language_program').relative_to(r))
  assert (r/(stem+'.log')).exists() and (r/(stem+'.stderr')).exists()
  lines.append(f'| {m} | {name} | {rc} | {seconds} | `{stem}.log` | `{stem}.stderr` |')
lines+=['','Void labels beginning `language_` other than `language_program` are internal substep statuses emitted by the fixed script; they are not added cases. A nonzero exit is retained as failure. Lifecycle/action transport records are in `control/alma/status.tsv` and `control/void/lifecycle.tsv`.','','## Collector coverage and cleanup','']
for m,s in summaries.items():
 if not s['inventory']:continue
 meta=s['metadata'];lines.append(f'- {m}: {s["queries"]} queries, {s["failed_queries"]} nonzero exits; collector `filesystem_complete={str(meta["filesystem_complete"]).lower()}`, `package_ownership_complete={str(meta["package_ownership_complete"]).lower()}`. Every query, stdout/stderr and gap remains in `raw/{m}/coverage.tsv`, `raw/{m}/raw/` and `raw/{m}/metadata.json`.')
lines+=['','Talos has second-level rows but explicitly lacks complete non-package inventory: bounded API traversal, unknown persistence and file integrity, and parser/ownership limitations remain. For other machines, a completeness flag describes the implemented collector scope only. No failed query is repaired or repeated. All facts and unavailable facts are indexed by `FACTS.md`.','','Every created disposable machine was destroyed. All temporary server task staging and duplicate outputs were removed after verified transfer; the 44 runtime inputs still matched before removal. See per-machine lifecycle records and `control/final-cleanup.json`. Raw transfer checksums and `control/table-verification.json` document byte preservation and exact one-to-one object-table transformation; these are mechanical checks, not independent acceptance of the experiment.','','## Deviations and earlier stop','','- Earlier pre-observation stop: `D1.stopped-before-observation/in/READY.md` records a mismatch in the publication-list checksum, with no machine, action, collector or observation. The corrected manifest was committed in `b3c3c14` before this run. The earlier record is preserved; only its READY file was read.','- SSH transport initially rejected a system configuration file because of its ownership/permissions. Explicit selection of the existing user SSH configuration restored transport without system edits or changes to committed inputs.','- MicroOS operator launch preparation failed twice before its sole machine command: the first launcher exited without retained diagnostics and was renamed from `operator.py` to avoid a possible standard-library name collision; the next service command rejected an unexpanded output path. The corrected launch invoked `lab.sh new` once. Exact available evidence and the missing first-launch diagnostic are disclosed in `control/OPERATOR-NOTES.md`.','- Void had one failed completion-monitor transport call (exit 255) while its detached entry script continued. Later monitoring reconnected; no action was retried. The exit status is retained in `control/void/lifecycle.tsv`; `control/void/action-completion.stderr` is empty, so the cause remains unknown.','- Gentoo startup failure prevented its prescribed actions and inventory; cause remains unknown. The failed case was not retried.','- AlmaLinux and Void collector invocation differed from the documented direct command: the operator used `bash D1/inputs/collect.sh --observe ...`, overriding the committed wrapper shebang (`/bin/sh`). This was an operator harness choice without a documented requirement or observed compatibility failure. The wrapper bytes and Python collector were unchanged; both invocations completed once and were not rerun. Evidence: `control/alma/operator.sh`, `control/void/operator.sh`.',
'- No committed collector, action command or installation recipe was modified or substituted. No objects were selected, filtered, merged or discarded. Remaining operational details are in the machine summaries and retained logs.','','No hypothesis outcome is assigned. This operator record is submitted for independent acceptance; it is not self-accepted.']
(r/'READY.md').write_text('\n'.join(lines)+'\n')
facts=['# Inventory fact index','',f'Recorded UTC: {now}.','','This index reports only retained collector facts. Unknown values remain unknown; no new queries were added to fill gaps. Every evidence reference in a part row is interpreted relative to its `D1/in/raw/<machine>/` directory. The `machine` field retains the collector target name, while `part` is the requested system identifier. Prefix removal is an exact id mapping; references inside raw member/fact tables retain the original collector ids.','']
for m in machines:facts.append((r/f'{m}-FACTS.md').read_text())
(r/'FACTS.md').write_text('\n'.join(facts))
(r/'control/combined-summary.json').write_text(json.dumps(summaries,indent=2)+'\n')
print(lines[0]);print({m:s['total'] for m,s in summaries.items()})
